      input: 250_000,
      output: 40_000,
      cache_read: 1 * M,
      cache_write: 400_000,
    });
    // 0.5 + 0.4 + 0.1 + 1.0
    expect(r.usd).toBeCloseTo(2.0, 10);
    expect(r.row_id).toBe("claude-sonnet-5-5");
  });
